const products = $('Load Approved Products').all().map(i => i.json || {}).filter(p => p.product_key);
const htmlItem = $input.first()?.json || {};
const html = String(htmlItem.data || htmlItem.body || '');
let followers = 1607;
const m = html.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__"[^>]*>(.*?)<\/script>/);
if (m) {
  try {
    const parsed = JSON.parse(m[1]);
    const ui = parsed?.__DEFAULT_SCOPE__?.['webapp.user-detail']?.userInfo || {};
    followers = Number(ui?.stats?.followerCount || followers);
  } catch (e) {}
}

// Only run the real Apify discovery when the weekly Sunday trigger (or manual run) fired —
// the daily 07:00 radar only evaluates the account and must not scrape every day.
let weeklyRun = false;
try { weeklyRun = !!($('Sunday 06:30 Weekly Apify Trend Discovery').isExecuted || $('Manual Trigger').isExecuted); } catch (e) { weeklyRun = new Date().getDay() === 0; }
if (!weeklyRun) return [];

// Everything already in the catalog (by product_key and DE product_id) is excluded from discovery
const existingKeys = new Set(products.map(p => String(p.product_key)));
const existingIds = new Set();
for (const p of products) {
  if (p.de_product_id) existingIds.add(String(p.de_product_id));
  const idm = String(p.tiktok_shop_url || '').match(/(\d{10,})/);
  if (idm) existingIds.add(idm[1]);
}
// Stale candidates: auto-pause candidates older than 14 days (catalog hygiene) — flag for downstream
const staleCandidates = products.filter(p => String(p.status) === 'candidate' && p.createdAt && (Date.now() - new Date(p.createdAt).getTime()) > 14 * 86400000).map(p => p.product_key);

// Weekly rotating German niche keyword batches — REAL discovery via Apify DE TikTok Shop scrape
const keywordGroups = [
  ['tiktok gadget', 'küchen gadget', 'auto zubehör', 'handy zubehör', 'led licht', 'reinigung', 'organizer', 'smart home', 'praktisch', 'angebot'],
  ['magsafe', 'powerbank', 'skincare', 'gesichtsmaske', 'beauty', 'haarpflege', 'wellness', 'pflege', 'schreibtisch', 'büro'],
  ['haustier', 'fitness', 'reise gadget', 'outdoor', 'viral produkt', 'life hack', 'problem löser', 'genial', 'neuheit', 'küchenhelfer']
];
const weekIdx = Math.floor(Date.now() / (7 * 24 * 3600 * 1000));
const keywords = keywordGroups[weekIdx % keywordGroups.length];

const items = staleCandidates.map(k => ({ json: { product_key: k, new_status: 'paused', stale_pause: true } }));
items.push({
  json: {
    de_keywords_json: JSON.stringify(keywords),
    existing_ids_json: JSON.stringify([...existingIds]),
    existing_keys_json: JSON.stringify([...existingKeys]),
    stale_candidates_json: JSON.stringify(staleCandidates),
    account_followers: followers,
    radar_week: 'kw-group-' + (weekIdx % keywordGroups.length),
    apify_custom_body: JSON.stringify({ country: 'DE', searchKeywords: keywords, maxProducts: 8, sortBySoldCount: 'highest_first', includeReviews: false })
  }
});
return items;

const raw = $input.first()?.json || {};
const q = raw.callback_query || raw;
const queryId = String(q.id || '');
const msg = q.message || {};
const data = String(q.data || '');
const parts = data.split('|');
const cmd = parts[0] || '';
const productKey = parts[1] || '';

let newStatus = 'approved';
let label = '✅ Produkt freigegeben (status = approved) — wird automatisch produziert!';
if (cmd === 'tts_pause') {
  newStatus = 'paused';
  label = '⏸️ Produkt pausiert (status = paused) — wird übersprungen.';
} else if (cmd === 'tts_winner') {
  newStatus = 'winner';
  label = '🏆 Produkt als WINNER markiert (status = winner) — Dauer-Skalierung aktiv!';
}

return [{
  json: {
    query_id: queryId,
    product_key: productKey,
    new_status: newStatus,
    answer_text: label,
    chat_id: msg.chat?.id || $env.TELEGRAM_CHAT_ID
  }
}];

const meta = ($('Evaluate Account & Sunday Apify 5-Candidate Radar').first() || {}).json || {};
const existingIds = new Set(JSON.parse(meta.existing_ids_json || '[]'));
const existingKeys = new Set(JSON.parse(meta.existing_keys_json || '[]'));
const followers = meta.account_followers || 0;

const scraped = $input.all().map(i => i.json || {}).filter(x => x.product_id);

// Dedupe by product_id (keep best sold_count), drop anything already in the catalog
const byId = new Map();
for (const s of scraped) {
  const id = String(s.product_id);
  if (existingIds.has(id)) continue;
  const prev = byId.get(id);
  if (!prev || Number(s.sold_count || 0) > Number(prev.sold_count || 0)) byId.set(id, s);
}

const catOf = t => {
  t = String(t || '').toLowerCase();
  if (/haut|creme|serum|maske|beauty|kollagen|collagen|skincare|gesicht|haar|pflege/.test(t)) return 'beauty_skincare';
  if (/auto|car |kfz|halterung|ladegerät|carplay|fahrzeug/.test(t)) return 'car_smart_accessories';
  if (/lampe|licht|led|küche|reinigung|organizer|schrank|haushalt|aufbewahrung/.test(t)) return 'smart_home_everyday';
  return 'tech_desk_gadgets';
};
const slug = t => String(t || '').toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 38);

// Selection score: DE sold_count primary, impulse price band bonus, packshot required-ish
const score = s => {
  let sc = Number(s.sold_count || 0);
  const price = Number(s.price || 0);
  if (price >= 8 && price <= 35) sc *= 1.3;
  else if (price < 5 || price > 60) sc *= 0.4;
  if (!s.image_url) sc *= 0.4;
  return sc;
};

const ranked = [...byId.values()].sort((a, b) => score(b) - score(a)).slice(0, 5);

const out = [];
for (const s of ranked) {
  const deId = String(s.product_id);
  const title = String(s.title || 'TikTok Shop Produkt').slice(0, 250);
  let key = 'prod_' + (slug(title) || ('item_' + deId));
  if (existingKeys.has(key)) key = 'prod_' + deId;
  const link = s.url ? String(s.url) : ('https://shop.tiktok.com/de/pdp/' + deId);
  const price = Number(s.price || 0);
  const sold = Number(s.sold_count || 0);
  const seller = (s.seller && s.seller.name) ? String(s.seller.name) : 'TikTok Shop DE Händler';
  const cat = catOf(title);
  const packshot = String(s.image_url || '');
  const appDeepLink = 'https://www.tiktok.com/view/product/' + deId;

  const tg = [
    '🇩🇪 <b>Neuer Radar-Kandidat (DE TikTok Shop)</b>',
    '<b>Original-Titel (DE Shop):</b> ' + title,
    '<b>DE Produkt-ID:</b> <code>' + deId + '</code> (' + seller + ')',
    '<b>Preis & Verkäufe (DE):</b> ' + price + ' EUR | ' + sold + ' verkauft | ~20% Provision (Schätzung)',
    '<b>Kategorie:</b> ' + cat + ' | <b>Keyword:</b> ' + String(s.search_query || ''),
    '<b>DE Shop-Link (PDP):</b> <a href="' + link + '">shop.tiktok.com/de/pdp/' + deId + '</a>',
    '<b>In-App Produkt-Link:</b> <a href="' + appDeepLink + '">tiktok.com/view/product/' + deId + '</a>',
    '<b>Original-Produktbild:</b> <a href="' + packshot + '">Packshot öffnen</a>',
    '',
    '<i>Tippe unten auf einen Button, um den Status in tts_products sofort zu steuern:</i>'
  ].join('
');

  out.push({
    json: {
      product_key: key,
      de_product_id: deId,
      product_name: title,
      category: cat,
      search_keyword: String(s.search_query || ''),
      tiktok_shop_url: link,
      packshot_image_url: packshot,
      price_eur: price,
      commission_pct: 20,
      sales_30d_est: sold,
      problem_solved: title,
      key_specs: title,
      flop_alternatives_json: '[]',
      status: 'candidate',
      account_followers: followers,
      cb_approve: 'tts_approve|' + key,
      cb_pause: 'tts_pause|' + key,
      cb_winner: 'tts_winner|' + key,
      tg_text: tg
    }
  });
}
return out;
